def install_runtime(root=None):
    raw=zlib.decompress(base64.b85decode(SOURCE_B85))
    if hashlib.sha256(raw).hexdigest()!=SOURCE_SHA256:
        raise ValueError('Treyrin architecture source is damaged')
    directory=Path(os.environ.get('TREYRIN_RUNTIME_DIR',
        str(Path(os.environ.get('LOCALAPPDATA',tempfile.gettempdir()))/'Treyrin/runtime')))
    destination=directory/SOURCE_SHA256[:20]/'internal'
    for relative,text in json.loads(raw).items():
        path=destination/relative
        if not path.resolve().is_relative_to(destination.resolve()):
            raise ValueError('Invalid bundled source path')
        data=text.encode('utf-8')
        if not path.is_file() or path.read_bytes()!=data:
            path.parent.mkdir(parents=True,exist_ok=True)
            temporary=path.with_suffix('.py.tmp')
            temporary.write_bytes(data);os.replace(temporary,path)
    return destination

